    bool accept(const std::string &);
    Token take(const std::string &);
    Token name();
    void recover_item();
    Item item();
    Group *group();
    Binding *binding();
    Expr *expression();
    Arm arm();
    Expr *binary(int);
    Expr *unary();
    Expr *atom();
    Expr *pattern();
    Expr *pattern_atom();
    Expr *type_expression();
    Expr *list_type();
    Expr *type_atom();
};
